-- Indonesian Media Network schema
CREATE TABLE IF NOT EXISTS media_groups (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS media_outlets (
  id SERIAL PRIMARY KEY,
  group_id TEXT REFERENCES media_groups(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  is_group_header BOOLEAN DEFAULT FALSE,
  url TEXT,
  total_brands INTEGER,
  harga_agency TEXT,
  harga_rate_card TEXT,
  google_news BOOLEAN DEFAULT FALSE,
  instagram_handle TEXT,
  instagram_followers TEXT,
  facebook_handle TEXT,
  facebook_followers TEXT,
  threads_handle TEXT,
  threads_followers TEXT,
  tiktok_handle TEXT,
  tiktok_followers TEXT,
  twitter_handle TEXT,
  twitter_followers TEXT,
  youtube_handle TEXT,
  youtube_followers TEXT,
  genre TEXT,
  keterangan TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_media_outlets_group ON media_outlets(group_id);

